// src/components/WalletConnect.js
import React, { useState, useEffect, useCallback } from 'react';
import { BrowserProvider, formatEther } from 'ethers';

function WalletConnect({ onWalletConnected }) {
  const [account, setAccount] = useState(null);
  const [balance, setBalance] = useState(null);
  const [chainId, setChainId] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [isMetaMaskInstalled, setIsMetaMaskInstalled] = useState(false);

  const NETWORKS = {
    '0x1': { name: 'Ethereum Mainnet', color: '#627EEA' },
    '0x5': { name: 'Goerli Testnet', color: '#308DFF' },
    '0x89': { name: 'Polygon', color: '#8247E5' },
    '0x13881': { name: 'Mumbai', color: '#8247E5' },
    '0x539': { name: 'Local Hardhat', color: '#F39C12' }
  };

  // Cập nhật thông tin từ MetaMask
  const fetchInfo = useCallback(async () => {
    if (!window.ethereum) return;
    try {
      const accounts = await window.ethereum.request({ method: 'eth_accounts' });
      const currentChainId = await window.ethereum.request({ method: 'eth_chainId' });
      
      if (accounts.length > 0) {
        // Kiểm tra xem người dùng có từng nhấn "Ngắt kết nối" không
        if (localStorage.getItem('user_disconnected') === 'true') {
          return;
        }

        const provider = new BrowserProvider(window.ethereum);
        const balanceBigInt = await provider.getBalance(accounts[0]);
        const formattedBalance = formatEther(balanceBigInt);

        setAccount(accounts[0]);
        setBalance(formattedBalance);
        setChainId(currentChainId);
        
        if (onWalletConnected) {
          onWalletConnected({ account: accounts[0], balance: formattedBalance, chainId: currentChainId });
        }
      }
    } catch (err) {
      console.error("Lỗi đồng bộ:", err);
    }
  }, [onWalletConnected]);

  // Thiết lập ban đầu và lắng nghe sự kiện
  useEffect(() => {
    setIsMetaMaskInstalled(!!window.ethereum);
    if (window.ethereum) {
      fetchInfo();

      // Sự kiện đổi mạng - Tải lại trang triệt để nhất
      const chainChanged = () => window.location.reload();
      // Sự kiện đổi tài khoản
      const accountsChanged = (accounts) => {
        if (accounts.length === 0) {
          // Người dùng đã ngắt quyền truy cập từ chính MetaMask
          localStorage.setItem('user_disconnected', 'true');
          setAccount(null);
          if (onWalletConnected) onWalletConnected(null);
        } else {
          fetchInfo();
        }
      };

      window.ethereum.on('chainChanged', chainChanged);
      window.ethereum.on('accountsChanged', accountsChanged);

      return () => {
        window.ethereum.removeListener('chainChanged', chainChanged);
        window.ethereum.removeListener('accountsChanged', accountsChanged);
      };
    }
  }, [fetchInfo, onWalletConnected]);

  const connectWallet = async () => {
    if (!window.ethereum) return;
    setError('');
    setLoading(true);
    try {
      const accounts = await window.ethereum.request({ method: 'eth_requestAccounts' });
      localStorage.removeItem('user_disconnected'); // Cho phép tự động kết nối lại lần sau
      await fetchInfo();
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const disconnectWallet = () => {
    localStorage.setItem('user_disconnected', 'true'); // Đánh dấu là người dùng chủ động ngắt kết nối
    setAccount(null);
    setBalance(null);
    setChainId(null);
    if (onWalletConnected) onWalletConnected(null);
  };

  const shortenAddress = (address) => `${address.slice(0, 6)}...${address.slice(-4)}`;
  const getNetwork = (id) => NETWORKS[id] || { name: `Mạng khác (${id})`, color: '#6c757d' };

  return (
    <div className="modern-wallet-card">
      <div className="glass-header">
        <div className="brand">
          <span className="brand-dot"></span>
          <h2>Trạng thái ví</h2>
        </div>
        <span className={`status-badge ${isMetaMaskInstalled ? 'success' : 'error'}`}>
          {isMetaMaskInstalled ? 'MetaMask Sẵn sàng' : 'Không tìm thấy MetaMask'}
        </span>
      </div>

      <div className="wallet-body">
        {!account ? (
          <div className="disconnected-view">
            <div className="visual-container">
              <div className="glow-circle"></div>
              <span className="main-emoji">🦊</span>
            </div>
            <h3>Kết nối ngay</h3>
            <p>Ứng dụng yêu cầu kết nối ví MetaMask để thực hiện các thao tác trên Blockchain.</p>
            <button onClick={connectWallet} disabled={loading} className="modern-btn primary">
              {loading ? "Đang xử lý..." : "Kết nối MetaMask"}
            </button>
            {error && <p className="error-text">❌ {error}</p>}
          </div>
        ) : (
          <div className="connected-view">
            <div className="bento-grid">
              <div className="bento-item account">
                <span className="label">Ví của bạn</span>
                <div className="value-row">
                  <span className="value">{shortenAddress(account)}</span>
                  <button onClick={() => navigator.clipboard.writeText(account)} className="copy-btn-modern">📋</button>
                </div>
              </div>
              <div className="bento-item balance">
                <span className="label">Số dư</span>
                <span className="value balance-text">{parseFloat(balance).toFixed(4)} <small>ETH</small></span>
              </div>
              <div className="bento-item network">
                <span className="label">Hệ thống mạng</span>
                <div className="network-status-pill" style={{ '--network-color': getNetwork(chainId).color }}>
                  <span className="network-dot"></span>
                  <span className="network-name">{getNetwork(chainId).name}</span>
                </div>
              </div>
            </div>
            <button onClick={disconnectWallet} className="modern-btn outline">Ngắt kết nối</button>
          </div>
        )}
      </div>
    </div>
  );
}

export default WalletConnect;
